// variants, so the page never accumulates duplicates.
var MANAGED_CONFLUENCE_SECTIONS = ['## Diagram', '## Affected Repositories'];

function stripManagedConfluenceSections(markdown) {
    if (!markdown) return markdown;
    var result = markdown;
