        if (contentOutput.isConfluenceTarget(outputCfg)) {
            var confFailure = publishSolutionToConfluence({
                outputCfg: outputCfg,
                tracker: tracker,
                ticketKey: ticketKey,
                ticketFields: params.ticket.fields,
                solutionField: solutionField,
                solution: solution,
                diagram: diagram,
                readOutput: readOutput
            });
